        counter = { { guid = "a7", name = "Подмастерье", wounds = 8, maxWounds = 8, order = "Engage", state = "used", canActivate = true } } }
    vm.foot = { { cmd = "passcounter", label = "Пропустить контрдействие", flex = true } }
    return vm
end

