function HubSample.all()
    local out = {}
    for _, name in ipairs({ "setup", "turn", "turnPending", "turnIdle", "turnPhase", "squad", "ploys", "enemy", "log", "score", "ref",
        "rail" }) do
        out[name] = { KT.hub.dock(HubSample[name]()) }
    end
    return out
end

