function HubSample.rich()
    local samples = {["1"]={["title"]="Верный последователь",["body"]="<b>Эффект</b>\nПримените этот приём перестрелки, когда дружественный оперативник Тёмного синода (DARK COMMUNE) из Культа Хаоса (CHAOS CULT) выбран допустимой целью действия «Стрельба» (Shoot) или должен стать противником в действии «Ближний бой» (Fight). Выберите вместо него другого дружественного оперативника Культа Хаоса, кроме DARK COMMUNE, который виден этому оперативнику DARK COMMUNE и находится в пределах 3 дюймов от него. Выбранный оперативник становится допустимой целью или противником в ближнем бою соответственно, даже если обычно он не мог бы им быть. При действии Fight считайте его находящимся в дистанции контроля сражающегося оперативника до конца этого действия. При действии Shoot он считается находящимся в укрытии или заслонённым только в том случае, если первоначальная цель находилась в укрытии или была заслонена. Эффект не действует при Shoot, если дальнобойное оружие имеет правило «Взрыв» (Blast) или «Поток» (Torrent).\n\n<b>Описание</b>\nТолпы Культа Хаоса без колебаний жертвуют жалкими жизнями, лишь бы защитить нечестивых господ."},["2"]={["title"]="Бессмертный деспотек — Межпространственное командование (Interstitial Command)",["body"]="<b>Межпространственное командование (Interstitial Command)</b>\n1 AP, ПОДДЕРЖКА (SUPPORT). Выберите другого дружественного оперативника Круга Иеротек (HIEROTEK CIRCLE), кроме Подмастерья (APPRENTEK) и Криптека (CRYPTEK). Он должен быть видим этому оперативнику и в пределах 6 дюймов от него; либо видим дружественному Деспотеку (DESPOTEK) и в пределах 6 дюймов от него, при этом Деспотек видим этому оперативнику. Выбранный оперативник немедленно бесплатно выполняет действие стоимостью 1 AP, кроме «Ускорения» (Accelerate), перемещаясь либо выставляясь заново не дальше чем на 2 дюйма. Нельзя выбрать действие, уже выполненное выбранным оперативником в этом раунде; он также не может повторить выбранное действие в этом раунде. Нельзя выполнять это действие в дистанции контроля врага либо во время контрдействия (Counteract)."},["3"]={["title"]="Плазмацит-реаниматор — Реанимация (Reanimate)",["body"]="<b>Реанимация (Reanimate)</b>\n1/2 AP. Выберите свой маркер Реанимации, видимый этому оперативнику и находящийся в пределах 6 дюймов. Бросьте D6: при результате 3+ дружественный оперативник РЕАНИМИРУЕТСЯ; если потратить ещё 1 AP, он автоматически РЕАНИМИРУЕТСЯ без броска. Если этот боец уже был использован в текущем раунде, после реанимации выставьте его использованным. Нельзя выполнять в зоне контроля врага."},["4"]={["title"]="Кукловод",["body"]="Кукловод (Mastermind): один раз за раунд, после встречного броска для определения инициативы, если этот оперативник находится в зоне боя, вы можете выбрать один вариант:\n- Добавить 1 к своему результату.\n- Если в предыдущем раунде у вас не было инициативы, перебросить свой кубик."},["5"]={["title"]="Сговор",["body"]="Заговор (Conspire):\n▶ Вы получаете 1 командное очко (CP).\n◆ Это действие нельзя выполнять в пределах дистанции контроля вражеского оперативника или более одного раза за раунд."}}
    local kids = {}
    for i = 1, 5 do
        local s = samples[tostring(i)]
        kids[#kids + 1] = KT.card({ KT.text(s.title, { w = 536, size = 15, bold = true }), KT.rich(s.body, { w = 536, size = 14, title = s.title }) }, { w = 560 })
    end
    local col = KT.vstack(kids, { w = 560, gap = 12 })
    col.attributes.rectAlignment = "UpperLeft"; col.attributes.offsetXY = "20 -20"; col.attributes.width = "560"; col.attributes.height = col.attributes.preferredHeight
    return col
end

