    local vm = HubSample.squad()
    vm.squad.view = "book"
    vm.squad.book = {["title"]="Круг Иеротек",["english"]="Hierotek Circle",["sections"]={{["key"]="rules",["title"]="Правила отряда",["items"]={{["key"]="93f9bd78cd76e0bc",["title"]="Бессмертный деспотек — Межпространственное командование",["english"]="Immortal Despotek — Interstitial Command",["body"]="<b>Межпространственное командование (Interstitial Command)</b>\n1 AP, ПОДДЕРЖКА (SUPPORT). Выберите другого дружественного оперативника Круга Иеротек (HIEROTEK CIRCLE), кроме Подмастерья (APPRENTEK) и Криптека (CRYPTEK). Он должен быть видим этому оперативнику и в пределах 6 дюймов от него; либо видим дружественному Деспотеку (DESPOTEK) и в пределах 6 дюймов от него, при этом Деспотек видим этому оперативнику. Выбранный оперативник немедленно бесплатно выполняет действие стоимостью 1 AP, кроме «Ускорения» (Accelerate), перемещаясь либо выставляясь заново не дальше чем на 2 дюйма. Нельзя выбрать действие, уже выполненное выбранным оперативником в этом раунде; он также не может повторить выбранное действие в этом раунде. Нельзя выполнять это действие в дистанции контроля врага либо во время контрдействия (Counteract).",["open"]=true},{["key"]="da3acdb34ea63850",["title"]="Плазмацит-реаниматор — Реанимация",["english"]="Plasmacyte Reanimator — Reanimate",["body"]="<b>Реанимация (Reanimate)</b>\n1/2 AP. Выберите свой маркер Реанимации, видимый этому оперативнику и находящийся в пределах 6 дюймов. Бросьте D6: при результате 3+ дружественный оперативник РЕАНИМИРУЕТСЯ; если потратить ещё 1 AP, он автоматически РЕАНИМИРУЕТСЯ без броска. Если этот боец уже был использован в текущем раунде, после реанимации выставьте его использованным. Нельзя выполнять в зоне контроля врага.",["open"]=true},{["key"]="f26d587e756e9e22",["title"]="Действия психоманта",["english"]="Psychomancer Actions",["body"]="<b>Покров кошмара (Nightmare Shroud)</b>\n1 AP. До начала следующей активации этого оперативника, его выведения из строя или повторного выполнения этого действия дружественным оперативником (что наступит раньше), когда враг в пределах 4 дюймов от него стреляет, участвует в ближнем бою или отвечает на удар, противник не может перебрасывать кубики атаки или сохранять результаты ниже 6 как критические успехи (например, благодаря свойствам «Смертоносное», «Раздирающее» или «Сокрушительное»). Нельзя выполнять в зоне контроля врага.\n\n<b>Видение безумия (Vision of Madness)</b>\n1 AP. Выберите видимого врага. До начала следующей активации этого оперативника, его выведения из строя или повторного выполнения действия дружественным оперативником (что наступит раньше) враг получает ваш жетон Безумия. Когда противник собирается активировать врага с таким жетоном, бросьте D6: если результат не меньше его лимита ОД (APL), его нельзя активировать в этой активации. Удалите жетон, если враг всё же активирован или если других доступных для активации врагов нет. Нельзя выполнять в зоне контроля врага.",["open"]=false}}},{["key"]="strat",["title"]="Стратегические уловки",["items"]={{["key"]="7d6e3e1cfaab5468",["title"]="Неумолимое наступление",["english"]="Relentless Onslaught",["body"]="<b>Эффект</b>\nКогда дружественный оперативник Круга Иеротек стреляет по оперативнику в пределах 8 дюймов от самого стрелка, дальнобойное оружие этого дружественного оперативника получает свойство «Сбалансированное» (Balanced). При использовании «Увеличения» (Magnify) сам стрелок всё равно должен находиться в пределах 8 дюймов от цели. Расстояние от другого оперативника, через которого определяется допустимая цель, не заменяет расстояние от стрелка до цели.\n\n<b>Описание</b>\nНеумолимые некроны компенсируют недостаток точности железной решимостью.",["open"]=false,["cost"]="1 CP"},{["key"]="2cfa7414d3eb916d",["title"]="Командование подчинёнными",["english"]="Command Underlings",["body"]="<b>Эффект</b>\nВыберите один вариант. Поддержка (SUPPORT): каждый другой дружественный оперативник Круга Иеротек, видимый Криптеку и находящийся в пределах 6 дюймов от дружественного Криптека, немедленно может бесплатно совершить рывок (Dash) в выбранном вами порядке; либо каждый другой дружественный оперативник Круга, кроме Криптека, видимый Подмастерью и находящийся в пределах 3 дюймов от дружественного Подмастерья, немедленно может бесплатно совершить рывок в выбранном порядке.\n\n<b>Описание</b>\nКриптеки и подмастерья управляют конструкциями и слугами как марионетками, сбивая врага с толку.",["open"]=false,["cost"]="1 CP"},{["key"]="7e0fef87fe11a70c",["title"]="Методичное уничтожение",["english"]="Methodical Elimination",["body"]="<b>Эффект</b>\nОружие ближнего боя дружественных оперативников Круга Иеротек получает свойство «Точное 1» (Accurate 1). Если дружественный оперативник сражается в активации, в которой переместился не больше своей характеристики Move, либо отвечает на удар, это оружие вместо этого получает свойство «Точное 2» (Accurate 2).\n\n<b>Описание</b>\nНекроны жертвуют скоростью ради стойкости и непрерывной огневой мощи.",["open"]=false,["cost"]="1 CP"},{["key"]="5a4d679fed98ed11",["title"]="Неумирающие автоматы",["english"]="Undying Androids",["body"]="<b>Эффект</b>\nКогда оперативник стреляет по дружественному оперативнику Круга Иеротек, если вы не можете сохранить ни одного спас-броска за укрытие, вы можете без броска сохранить один кубик защиты как обычный успех.\n\n<b>Описание</b>\nТела некронов из живого металла устойчивы к большинству орудий примитивных биологических видов.",["open"]=false,["cost"]="1 CP"}}},{["key"]="fire",["title"]="Уловки перестрелки",["items"]={{["key"]="96538a3d548cbd0e",["title"]="Живая молния",["english"]="Living Lightning",["body"]="<b>Эффект</b>\nПримените, когда дружественный Бессмертный (IMMORTAL) из Круга Иеротек выполняет действие «Стрелять» и выбирает карабин Теслы. До конца действия оружие теряет дистанционное условие 2 дюйма у свойства «Разрушительное» (Devastating) и получает свойство «Взрыв 2 дюйма» (Blast 2\").\n\n<b>Описание</b>\nОружие Теслы создаёт живую молнию, которая перескакивает между целями и вытягивает жизнь.",["open"]=false,["cost"]="1 CP"},{["key"]="185e0e8f7462686d",["title"]="Контроль корой",["english"]="Cortical Control",["body"]="<b>Эффект</b>\nПримените, когда дружественный Подмастерье (APPRENTEK) или Криптек (CRYPTEK) Круга Иеротек выполняет уникальное действие с тегом «Поддержка» (SUPPORT). До конца действия при выборе другого дружественного оперативника игнорируйте ограничение по дистанции; видимость по-прежнему необходима.\n\n<b>Описание</b>\nКриптеки и их подмастерья проецируют волю в сознание каноптекских конструкций на огромные расстояния.",["open"]=false,["cost"]="1 CP"},{["key"]="814543083a874bf9",["title"]="Повторно активированная функция",["english"]="Reanimated Function",["body"]="<b>Эффект</b>\nПримените при определении контроля над маркером. Выберите свой маркер Реанимации. До начала следующего раунда при определении контроля над любым маркером считайте выбранный маркер Реанимации дружественным оперативником Круга Иеротек с лимитом AP (APL), равным 1.\nДля операции «Мученики» (Martyrs) из Approved Ops 2025 эта уловка не имеет эффекта.\n\n<b>Описание</b>\nПостоянное восстановление павших некронов помогает Кругу всё крепче удерживать цели.",["open"]=false,["cost"]="1 CP"},{["key"]="7c4bf333c7fe80bb",["title"]="Межпространственная засада",["english"]="Dimensional Ambush",["body"]="<b>Эффект</b>\nПримените во время активации дружественного Метчика смерти (DEATHMARK) из Круга Иеротек, если у него приказ «Скрытность» (Conceal). Во время этой активации он может выполнять действие «Охрана» (Guard) независимо от зоны боя и, сохраняя приказ Скрытность. Когда он выполняет бесплатное действие «Ближний бой» (Fight) или «Стрелять» (Shoot) во время прерывания, смените его приказ на «Бой» (Engage).\n\n<b>Описание</b>\nМетчик смерти раскрывает своё местоположение лишь тогда, когда появляется возможность нанести смертельный выстрел.",["open"]=false,["cost"]="1 CP"}}},{["key"]="eq",["title"]="Снаряжение",["items"]={{["key"]="0afc2316bf68f135",["title"]="Каналы увеличения",["english"]="Magnification Conduits",["body"]="<b>Каналы увеличения (Magnification Conduits)</b>\nРаз за раунд, когда дружественный Подмастерье (APPRENTEK) или Криптек (CRYPTEK) Круга Иеротек выполняет Стрельбу (Shoot), можно выбрать другого дружественного оперативника Круга Иеротек, кроме Плазмацита (PLASMACYTE). Он должен иметь приказ «Бой» (Engage), быть видим стрелку и не находиться в дистанции контроля врагов. До конца действия выбранный боец может считаться активным оперативником для правила «Увеличение» (Magnify).\n\n<b>Описание</b>\nУстройство позволяет некрону, сведущему в тайной гипертехнологии, направлять дальнобойные атаки через ближайшего подчинённого.",["open"]=false},{["key"]="1eadd0586a1cf549",["title"]="Фазовый сдвигатель",["english"]="Phase Shifter",["body"]="<b>Фазовый сдвигатель (Phase Shifter)</b>\nРаз за раунд, когда враг стреляет по дружественному Криптеку и вы собираете кубики защиты, до конца последовательности уменьшите значение X у свойства «Бронебойное X» (Piercing X) на 1, если оно есть. Бронебойное 1 игнорируется.\n\n<b>Описание</b>\nКриптек может мгновенно сместиться между измерениями и уклониться от летящего снаряда.",["open"]=false},{["key"]="19b05d9b157c60b3",["title"]="Тессерактовый куб",["english"]="Tesseract Cube",["body"]="<b>Тессерактовый куб (Tesseract Cube)</b>\nНа шаге подготовки каждой фазы стратегии, когда вы получаете ОК (CP), если дружественный Криптек не выведен из строя, не находится в зоне контроля врага и не был РЕАНИМИРОВАН в этом раунде, бросьте D6. При 1 больше нельзя применять это правило до конца битвы; при 4+ получите 1 ОК. После получения таким способом 2 ОК правило больше нельзя применять.\n\n<b>Описание</b>\nЭто устройство межпространственной технологии вмещает гораздо больше, чем кажется, и хранит ресурсы и артефакты, добытые Кругом.",["open"]=false},{["key"]="e6f58da5ce6d5c05",["title"]="Тесла-сеть",["english"]="Tesla Weave",["body"]="<b>Тесла-сеть (Tesla Weave)</b>\nРаз за раунд, когда вражеский оперативник завершает Атаку (Charge) в зоне контроля дружественного оперативника Круга Иеротек, нанесите врагу D3+1 урона.\n\n<b>Описание</b>\nМолнии Теслы перескакивают между некронами и конструкциями Каноптек, опаляя попавших между ними врагов.",["open"]=false}}}}}
    vm.foot = { { note = "Все правила Круга Иеротек в одном месте" } }
    return vm
end

function HubSample.codex()
