    vm.tab = "codex"
    vm.codex = {["side"]="mine",["hasEnemy"]=true,["title"]="Круг Иеротек",["english"]="Hierotek Circle",["colorKey"]="Red",["scopes"]={{"roster","Состав"},{"rules","Правила",14},{"strat","Стратегия",4},{"fire","Перестрелка",4},{"eq","Снаряжение",4},{"faq","FAQ"}},["scope"]="rules",["query"]="",["listTitle"]="Правила отряда",["count"]=14,["results"]={{["key"]="k0",["title"]="Бессмертный деспотек — Межпространственное командование",["english"]="Immortal Despotek — Interstitial Command",["on"]=false},{["key"]="k1",["title"]="Плазмацит-реаниматор — Реанимация",["english"]="Plasmacyte Reanimator — Reanimate",["on"]=true},{["key"]="k2",["title"]="Действия психоманта",["english"]="Psychomancer Actions",["on"]=false},{["key"]="k3",["title"]="Действия психоманта — Межпространственное командование и Предвестник отчаяния",["english"]="Psychomancer Actions — Interstitial Command and Harbinger of Despair",["on"]=false},{["key"]="k4",["title"]="Действия техноманта",["english"]="Technomancer Actions",["on"]=false},{["key"]="k5",["title"]="Действия техноманта",["english"]="Technomancer Actions (reverse)",["on"]=false},{["key"]="k6",["title"]="Действия хрономанта",["english"]="Chronomancer Actions",["on"]=false},{["key"]="k7",["title"]="Действия хрономанта — Межпространственное командование и Хроноклинок",["english"]="Chronomancer Actions — Interstitial Command and Timesplinter",["on"]=false},{["key"]="k8",["title"]="Протоколы реанимации",["english"]="Reanimation Protocols",["on"]=false},{["key"]="k9",["title"]="Протоколы реанимации — продолжение",["english"]="Reanimation Protocols — continuation",["on"]=false},{["key"]="k10",["title"]="Отряд Круга Иеротек",["english"]="Hierotek Circle Kill Team",["on"]=false},{["key"]="k11",["title"]="Отряд Круга Иеротек — продолжение списка",["english"]="Hierotek Circle Kill Team — continuation",["on"]=false},{["key"]="k12",["title"]="Живой металл",["english"]="Living Metal",["on"]=false},{["key"]="k13",["title"]="Увеличение",["english"]="Magnify",["on"]=false}},["article"]={["label"]="ПРАВИЛА ОТРЯДА",["team"]="Круг Иеротек",["title"]="Плазмацит-реаниматор — Реанимация",["english"]="Plasmacyte Reanimator — Reanimate",["body"]="<b>Реанимация (Reanimate)</b>\n1/2 AP. Выберите свой маркер Реанимации, видимый этому оперативнику и находящийся в пределах 6 дюймов. Бросьте D6: при результате 3+ дружественный оперативник РЕАНИМИРУЕТСЯ; если потратить ещё 1 AP, он автоматически РЕАНИМИРУЕТСЯ без броска. Если этот боец уже был использован в текущем раунде, после реанимации выставьте его использованным. Нельзя выполнять в зоне контроля врага.",["terms"]={{"g1","Видимый"},{"g2","В пределах"}}}}
    return vm
end
